import React, { useState, useEffect } from "react";
import { useForm } from "react-hook-form";
import { motion } from "framer-motion";
import api from "@landinghub/api";
import LeadKanban from "../components/LeadKanban";
import LeadList from "../components/LeadList";
import LeadEditModal from "../components/LeadEditModal";
import '../styles/leads.css'; // import CSS
import '../styles/leads_quanly.css'; // import CSS

// ========================= LandingForm =========================
const LandingForm = ({ onAdd }) => {
  const { register, handleSubmit, formState: { errors }, reset } = useForm();

  const onSubmit = async (data) => {
    try {
      await onAdd(data);
      alert("Cảm ơn! Lead của bạn đã được gửi.");
      reset();
    } catch (err) {
      alert("Lỗi: " + (err.response?.data?.error || err.message));
    }
  };

  return (
    <div className="landing-form-wrapper">
      <form onSubmit={handleSubmit(onSubmit)} className="landing-form">
        <h2 className="form-title">📩 Gửi thông tin của bạn</h2>

        <div className="form-group">
          <input {...register("name", { required: "Tên là bắt buộc" })} placeholder="Tên của bạn" />
          {errors.name && <p className="error-message">{errors.name.message}</p>}
        </div>

        <div className="form-group">
          <input {...register("email", { required: "Email là bắt buộc", pattern: { value: /^\S+@\S+$/i, message: "Email không hợp lệ" } })} placeholder="Email" type="email" />
          {errors.email && <p className="error-message">{errors.email.message}</p>}
        </div>

        <div className="form-group">
          <input {...register("phone", { required: "Số điện thoại là bắt buộc" })} placeholder="Số điện thoại" type="tel" />
          {errors.phone && <p className="error-message">{errors.phone.message}</p>}
        </div>

        <div className="form-group">
          <input {...register("company")} placeholder="Công ty" />
        </div>

        <div className="form-group">
          <input {...register("position")} placeholder="Vị trí công việc" />
        </div>

        <button type="submit" className="submit-btn">Gửi Leads</button>
      </form>
    </div>
  );
};

// ========================= Leads Page =========================
const Leads = () => {
  const [leads, setLeads] = useState([]);
  const [view, setView] = useState("kanban");
  const [draggedLead, setDraggedLead] = useState(null);
  const [editingLead, setEditingLead] = useState(null);

  // Lấy danh sách leads
  const fetchLeads = async () => {
    try {
      const res = await api.get("/api/leads");
      const data = Array.isArray(res.data)
        ? res.data
        : Array.isArray(res.data.data)
        ? res.data.data
        : [];
      setLeads(data);
    } catch (err) {
      console.error("Fetch leads error:", err);
    }
  };

  useEffect(() => { fetchLeads(); }, []);

  // Thêm lead
  const onAdd = async (form) => {
    const newLead = { ...form, status: "new" };
    try {
      const res = await api.post("/api/leads", newLead);
      setLeads([...leads, res.data]);
    } catch (err) {
      console.error("Add lead error:", err);
      setLeads([...leads, { ...newLead, _id: Date.now().toString() }]);
    }
  };

  // Xóa lead
  const onDelete = async (id) => {
    if (!window.confirm("Xóa lead này?")) return;
    try {
      await api.delete(`/api/leads/${id}`);
      setLeads(leads.filter((l) => l._id !== id));
    } catch (err) {
      console.error("Delete lead error:", err);
    }
  };

  // Drag & drop Kanban
  const onDragStart = (lead) => setDraggedLead(lead);
  const onDrop = async (newStatus, lead) => {
    if (!lead) return;
    const updatedLead = { ...lead, status: newStatus };
    setLeads((prev) => prev.map((l) => (l._id === lead._id ? updatedLead : l)));
    try {
      await api.put(`/api/leads/${lead._id}`, updatedLead);
    } catch (err) {
      console.error("Update lead error:", err);
    }
  };

  // Lưu chỉnh sửa popup
  const handleSaveEdit = async (form) => {
    try {
      const res = await api.put(`/api/leads/${form._id}`, form);
      const updated = res.data.data || form;
      setLeads((prev) => prev.map((l) => (l._id === form._id ? updated : l)));
      setEditingLead(null);
    } catch (err) {
      console.error("Update lead error:", err);
    }
  };

  // Inline update List view
  const onUpdateInline = (id, key, value) => {
    setLeads((prev) => prev.map((l) => (l._id === id ? { ...l, [key]: value } : l)));
  };

  return (
    <div className="p-6 bg-gray-100 min-h-screen relative">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-2xl font-semibold text-gray-700">📊 Quản lý Leads</h2>
        <div className="flex gap-2">
          <button
            onClick={() => setView("kanban")}
            className={`px-4 py-2 rounded ${view === "kanban" ? "bg-blue-600 text-white" : "bg-gray-200"}`}
          >🧩 Kanban</button>
          <button
            onClick={() => setView("list")}
            className={`px-4 py-2 rounded ${view === "list" ? "bg-blue-600 text-white" : "bg-gray-200"}`}
          >📋 Danh sách</button>
        </div>
      </div>

      {/* Landing Form */}
      <LandingForm onAdd={onAdd} />

      {/* View */}
      {view === "kanban" ? (
        <LeadKanban
          leads={leads}
          onUpdate={setLeads}
          onDelete={onDelete}
          onDrop={onDrop}
          onEdit={(lead) => setEditingLead(lead)}
          onDragStart={onDragStart}
        />
      ) : (
        <LeadList
          leads={leads}
          onUpdate={onUpdateInline}
          onDelete={onDelete}
          onEdit={(lead) => setEditingLead(lead)}
        />
      )}

      {/* Edit Modal */}
      {editingLead && (
        <LeadEditModal
          lead={editingLead}
          onClose={() => setEditingLead(null)}
          onSave={handleSaveEdit}
        />
      )}
    </div>
  );
};

export default Leads;
